/**
 * Redux page key, `Filter` `pageName`, thunk routing, and preset `/presets/…` HTTP segment.
 * Not used as the **bracket query prefix** for tier refresh (see `COMMERCIAL_RESULTS_PRESET_QUERY_BRACKET_PREFIX`).
 */
export const COMMERCIAL_RESULTS_PAGE_NAME = 'value-creation_commercial-results';

export const COMMERCIAL_RESULTS_LINE_BAR_CHARTS_BFF_ID = `${COMMERCIAL_RESULTS_PAGE_NAME}_line-bar-charts`;

export const COMMERCIAL_RESULTS_LINE_BAR_CHARTS_COMPONENT_ID =
  'line-bar-charts';
/** Path under the Martech OneWay Reports BFF prefix (same pattern as `/presets/{pageName}`). */
export const COMMERCIAL_RESULTS_PRESET_HTTP_PATH = `/presets/${COMMERCIAL_RESULTS_PAGE_NAME}`;

/**
 * BFF bracket param prefix for tiered preset `GET` query (drivers: zone, country, brand, periods).
 * Example: `commercial_results_filters[zone]=AFR`.
 */
export const COMMERCIAL_RESULTS_PRESET_QUERY_BRACKET_PREFIX =
  'commercial_results_filters';

/** Redux `form` keys sent as bracket sub-keys on preset refresh (omit empties). */
export const COMMERCIAL_RESULTS_PRESET_DRIVER_KEYS = [
  'zone',
  'country',
  'brands',
  'periods',
] as const;

/** Map form key → query sub-key when they differ (BFF contract). */
export const COMMERCIAL_RESULTS_PRESET_FORM_TO_QUERY_KEY: Partial<
  Record<(typeof COMMERCIAL_RESULTS_PRESET_DRIVER_KEYS)[number], string>
> = {
  brands: 'brand',
};

export const KPIS_TITLE_MAP = {
  power: 'Brand Power',
  volume: 'Volume',
  nr: 'Net Revenue',
  market_share: 'Market Share',
  cores: 'CORES',
};
export const KPIS_MEASURE_MAP = {
  power: '[ k hl ]',
  volume: '[ k hl ]',
  nr: '[ k hl ]',
  market_share: '[ k hl ]',
  cores: '[ k hl ]',
};

export const COMMERCIAL_RESULTS_PATH = '/value-creation/commercial-results';

export const BFF_ID_PREFIX = 'value-creation_commercial-results';

/** BFF view id for the Commercial Results contribution waterfall. */
export const COMMERCIAL_RESULTS_WATERFALL_BFF_ID =
  'value-creation_commercial-results_waterfall';

/** SubFilter dataApiKey for Commercial Results waterfall options. */
export const COMMERCIAL_RESULTS_WATERFALL_OPTIONS_DATA_API_KEY =
  'commercial-results-waterfall-options';

/** SubFilter apiKey prefix for Commercial Results waterfall options. */
export const COMMERCIAL_RESULTS_WATERFALL_OPTIONS_API_KEY_PREFIX =
  'commercial-results-waterfall-options';
export const COMMERCIAL_RESULTS_BIG_NUMBERS_SUB_FILTERS = {
  region: 'ALL',
  brand: 'ALL',
  sub_brand: 'ALL',
  sku: 'ALL',
  pack_type: 'ALL',
  channel: 'ALL',
} as const;
